// Package nativeaot synthesises NativeAOT C# wrapper projects for imported
// NuGet packages. For each package in the TranslatedSurface, it generates a
// .csproj file and a Src/Wrapper.cs file containing [UnmanagedCallersOnly]
// extern functions that bridge the .NET public API to a stable C ABI callable
// from the Mochi/Rust binary. See research note 09 (ABI stability) and note
// 10 (GC and memory) for the design rationale.
package nativeaot

import (
	"fmt"
	"path/filepath"
	"strings"

	"mochi/package3/dotnet/typemap"
)

// WrapperProject holds the generated files for one NuGet package's
// NativeAOT wrapper C# project.
type WrapperProject struct {
	PackageID   string
	CsprojPath  string
	WrapperPath string // Src/Wrapper.cs
	CsprojBody  string
	WrapperBody string
}

// SynthesisOptions controls code generation details.
type SynthesisOptions struct {
	// PackageID is the NuGet package id (e.g. "Newtonsoft.Json").
	PackageID string
	// PackageVersion is the resolved version (e.g. "13.0.3").
	PackageVersion string
	// TargetFramework is the TFM (e.g. "net9.0").
	TargetFramework string
	// RuntimeIdentifiers is the list of .NET RIDs to build for.
	RuntimeIdentifiers []string
	// OutDir is the directory where the wrapper project is emitted.
	OutDir string
}

// Synthesize generates the NativeAOT wrapper project for the given
// TranslatedSurface and returns the WrapperProject containing the file bodies.
// It does not write to disk; the caller is responsible for writing the files.
func Synthesize(surface *typemap.TranslatedSurface, opts SynthesisOptions) (*WrapperProject, error) {
	if opts.PackageID == "" {
		return nil, fmt.Errorf("nativeaot: package ID is required")
	}
	proj := &WrapperProject{
		PackageID:   opts.PackageID,
		CsprojPath:  filepath.Join(opts.OutDir, opts.PackageID+".csproj"),
		WrapperPath: filepath.Join(opts.OutDir, "Src", "Wrapper.cs"),
	}
	proj.CsprojBody = emitCsproj(opts)
	proj.WrapperBody = emitWrapper(surface, opts)
	return proj, nil
}

func emitCsproj(opts SynthesisOptions) string {
	tfm := opts.TargetFramework
	if tfm == "" {
		tfm = "net9.0"
	}
	var b strings.Builder
	b.WriteString(`<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Library</OutputType>
    <TargetFramework>`)
	b.WriteString(tfm)
	b.WriteString(`</TargetFramework>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
    <Nullable>enable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
    <PublishAot>true</PublishAot>
    <NativeLib>Static</NativeLib>
    <StripSymbols>true</StripSymbols>
    <InvariantGlobalization>true</InvariantGlobalization>
    <TrimmerRootDescriptor>ILLink.Descriptors.xml</TrimmerRootDescriptor>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="mochi-dotnet-runtime" Version="0.1.*" />
    <PackageReference Include="`)
	b.WriteString(opts.PackageID)
	b.WriteString(`" Version="[`)
	b.WriteString(opts.PackageVersion)
	b.WriteString(`]" />
  </ItemGroup>
</Project>
`)
	return b.String()
}

func emitWrapper(surface *typemap.TranslatedSurface, opts SynthesisOptions) string {
	var b strings.Builder
	b.WriteString("// Auto-generated by mochi package3/dotnet NativeAOT wrapper synthesizer.\n")
	b.WriteString("// MEP-68 phase 4. Do not edit by hand; regenerate with `mochi pkg sync dotnet`.\n\n")
	b.WriteString("using System.Runtime.InteropServices;\n")
	b.WriteString("using MochiDotnetRuntime;\n\n")
	b.WriteString("namespace MochiDotnetWrap;\n\n")
	b.WriteString("public static unsafe class Wrapper\n{\n")

	for _, item := range surface.Items {
		switch item.Kind {
		case typemap.ItemFn, typemap.ItemMethod, typemap.ItemConstructor:
			emitMethod(&b, item, opts)
		case typemap.ItemFreeSymbol:
			emitFreeSymbol(&b, item)
		}
	}

	// Emit the process-wide GC handle free for strings.
	b.WriteString(`
    [UnmanagedCallersOnly(EntryPoint = "mochi_dotnet_string_free")]
    public static void StringFree(byte* ptr)
    {
        if (ptr != null) Marshal.FreeHGlobal((nint)ptr);
    }
`)

	b.WriteString("}\n")
	return b.String()
}

func emitMethod(b *strings.Builder, item typemap.TranslatedItem, _ SynthesisOptions) {
	b.WriteString(fmt.Sprintf(
		"\n    [UnmanagedCallersOnly(EntryPoint = %q)]\n", item.Symbol))
	b.WriteString(fmt.Sprintf(
		"    public static %s %s(%s)\n    {\n",
		csharpReturnType(item.ReturnType),
		csharpMethodName(item.Symbol),
		csharpParams(item),
	))
	b.WriteString("        // TODO: phase 4 full implementation\n")
	b.WriteString("        throw new NotImplementedException();\n")
	b.WriteString("    }\n")
}

func emitFreeSymbol(b *strings.Builder, item typemap.TranslatedItem) {
	b.WriteString(fmt.Sprintf(
		"\n    [UnmanagedCallersOnly(EntryPoint = %q)]\n", item.Symbol))
	b.WriteString(fmt.Sprintf(
		"    public static void %s(nint handle)\n    {\n",
		csharpMethodName(item.Symbol)))
	b.WriteString("        GCHandleTable.Free(handle);\n")
	b.WriteString("    }\n")
}

func csharpReturnType(t typemap.MochiType) string {
	switch t.Kind {
	case typemap.MochiUnit:
		return "void"
	case typemap.MochiBool:
		return "byte" // bool is not blittable across [UnmanagedCallersOnly]
	case typemap.MochiInt:
		return "int"
	case typemap.MochiLong:
		return "long"
	case typemap.MochiFloat:
		return "double"
	case typemap.MochiString:
		return "byte*"
	case typemap.MochiExtern, typemap.MochiRecord:
		return "nint"
	default:
		return "nint" // generic fallback
	}
}

func csharpParams(item typemap.TranslatedItem) string {
	var parts []string
	if item.ReceiverType != nil {
		parts = append(parts, "nint _receiver")
	}
	for _, p := range item.Params {
		parts = append(parts, csharpReturnType(p.Type)+" "+p.Name)
	}
	return strings.Join(parts, ", ")
}

func csharpMethodName(symbol string) string {
	// Turn "mochi_dotnet_Pkg_Type_Method" into "Pkg_Type_Method" for C# method name.
	s := strings.TrimPrefix(symbol, "mochi_dotnet_")
	return s
}
